-- 0054 · Correct the payment status the first load got wrong
--
-- The register was loaded reading only the Paid Date column, so 78 requests
-- that the sheet records as settled by cheque, post-dated cheque or
-- liquidation came in as drafts. The rows already exist, and INSERT OR IGNORE
-- does not correct an existing row, so the status is set here.
--
-- Only the imported rows are touched. Anything a person raised in the system
-- keeps whatever status the system gave it.

UPDATE erp_payment_requests SET status='PAID', paid_at=COALESCE(paid_at,NULL), updated_at=datetime('now') WHERE request_no='LIQ-COMP2026-0001' AND requestor_email='procurement-register@nrdev.ph' AND status='DRAFT';
